// Private Firebase Storage. No tokenized download URL is generated by this app.
import {db} from "./firebase-config.js";
import {getAuth,onAuthStateChanged,GoogleAuthProvider,signInWithPopup,setPersistence,browserSessionPersistence} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import {getStorage,ref,uploadBytes,getBlob} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-storage.js";
const auth=getAuth(db.app),storage=getStorage(db.app),MAX=8*1024*1024;
const paths=new Map();let epoch=0,owner=null;
export const currentUser=()=>auth.currentUser;
function verified(){const u=auth.currentUser;if(!u?.emailVerified)throw Error("Accedi con Google usando un account verificato.");return u;}
function own(p){const u=verified();if(typeof p!=="string"||!/^recipe-drawings\/[A-Za-z0-9_-]{1,128}\/[a-f0-9-]{36}\.(jpg|png|webp)$/.test(p)||p.split("/")[1]!==u.uid)throw Error("Foto riservata a un altro account.");return u;}
export async function login(){await setPersistence(auth,browserSessionPersistence);const p=new GoogleAuthProvider();p.setCustomParameters({prompt:"select_account"});return signInWithPopup(auth,p);}
export function watch(callback){return onAuthStateChanged(auth,u=>{
 const next=u?.emailVerified?u.uid:null;
 if(next!==owner){owner=next;epoch++;for(const p of paths.values())p.then(url=>URL.revokeObjectURL(url)).catch(()=>{});paths.clear();}
 callback(u);
});}
export async function privateImage(path){
 const u=own(path),generation=epoch;
 if(!paths.has(path)){
  const p=(async()=>{
   const blob=await getBlob(ref(storage,path),MAX);
   if(auth.currentUser?.uid!==u.uid||generation!==epoch)throw Error("Sessione cambiata.");
   if(!/^image\/(jpeg|png|webp)$/.test(blob.type))throw Error("Formato immagine non consentito.");
   return URL.createObjectURL(blob);
  })();
  paths.set(path,p);p.catch(()=>{if(paths.get(path)===p)paths.delete(path);});
 }
 return paths.get(path);
}
export async function uploadPrivate(file){
 const user=verified(),ext={"image/jpeg":"jpg","image/png":"png","image/webp":"webp"}[file?.type];
 if(!ext||!file.size||file.size>MAX)throw Error("Usa JPG, PNG o WebP fino a 8 MB.");
 const path="recipe-drawings/"+user.uid+"/"+crypto.randomUUID()+"."+ext;own(path);
 await uploadBytes(ref(storage,path),file,{contentType:file.type,cacheControl:"private, no-store"});
 if(auth.currentUser?.uid!==user.uid)throw Error("Sessione cambiata.");
 await privateImage(path);return path;
}
